// Bundle the pinned Leaflet runtime into the app, avoiding a runtime CDN dependency.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const distribution = path.dirname(require.resolve('leaflet/dist/leaflet.js'));
const leafletJs = fs.readFileSync(path.join(distribution, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const leafletCss = fs.readFileSync(path.join(distribution, 'leaflet.css'), 'utf8');
fs.writeFileSync(path.join(root, 'src/vendor/leafletBundle.js'), '// Generated by scripts/bundle-leaflet.cjs. Leaflet 1.9.4, BSD-2-Clause; see leaflet-LICENSE.\nmodule.exports = ' + JSON.stringify({ leafletJs, leafletCss }) + ';\n');
fs.copyFileSync(path.join(distribution, '../LICENSE'), path.join(root, 'src/vendor/leaflet-LICENSE'));
console.log('Bundled Leaflet 1.9.4 locally.');
